import json
d=json.load(open('factory-agents/sm_github.json'))
def walk(o,path=''):
    if isinstance(o,dict):
        if 'id' in o and ('query' in o or 'localAction' in o):
            q=o.get('query',{})
            labels=q.get('labels') or q.get('notLabels')
            print(o.get('id'), '| action=',o.get('localAction'),'| labels=',labels,'| checks=',q.get('checks'))
        for k,v in o.items(): walk(v,path+'/'+str(k))
    elif isinstance(o,list):
        for i,v in enumerate(o): walk(v,path)
